#[path="crates/fluid-gpu/src/lbm/mod.rs"] mod lbm;
use lbm::*;
fn main(){let args:Vec<_>=std::env::args().collect();let fine=!args.iter().any(|s|s=="coarse");let frozen=args.iter().any(|s|s=="frozen");let profile=if fine{GridProfile::Fine}else{GridProfile::Coarse};let h=profile.cell_spacing();let n=profile.cells_per_side() as usize;let count=if fine{7}else{4};let dt=(1_f32/120.)/count as f32;let q0=18.529297_f32;let start=(21./h)as u32;let end=(27./h)as u32;let mut solid=vec![];let mut velocity=vec![];for _y in 0..n{let y=(_y as f32+0.5)*h;for _x in 0..n{let wall=(y-24.).abs()>=3.;solid.push(wall);velocity.push(if wall{[0.;2]}else{[q0/4.*(1.-((y-24.)/3.).powi(2)),0.]});}}
let geom=WindowGeometry{solid:solid.clone(),openings:vec![OpeningSpec{side:WindowSide::Left,cells:start..end,direction:[1.,0.],outward_flow:-q0,background_speed:q0/4.},OpeningSpec{side:WindowSide::Right,cells:start..end,direction:[1.,0.],outward_flow:q0,background_speed:q0/4.}]};let mut w=LbmWindow::new(WindowSpec{origin:WindowOrigin{block_x:0,block_y:0},profile},WindowConfig{dt,viscosity:0.05,allow_software:true},InitialField{density:vec![1.;n*n],velocity},geom).unwrap();println!("mode={} fine={fine} frozen={frozen} dt={dt} tau={}",std::env::var("LBMDIAG").unwrap_or_default(),0.5+3.*0.05*dt/(h*h));
for frame in 0..160{let q=q0*(1.+if frozen{0.}else{0.15*(std::f32::consts::TAU*1.2*frame as f32/60.).sin()});let weights:Vec<f32>=(start..end).map(|j|{let y=(j as f32+0.5)*h;(1.-((y-24.)/3.).powi(2)).max(0.)}).collect();let sum=weights.iter().sum::<f32>()*h;let profiles=vec![weights.iter().map(|v|-q*v/sum).collect(),weights.iter().map(|v|q*v/sum).collect()];w.set_opening_profiles(&[-q,q],&profiles).unwrap();for k in 0..count*2{w.advance(StepInput{acceleration:[0.;2]}).unwrap();let f=w.field().unwrap();let mut lo=(f32::INFINITY,0);let mut hi=(f32::NEG_INFINITY,0);let mut maxu=(0_f32,0);for(i,p)in f.iter().enumerate(){if solid[i]{continue}if p[0]<=0.||!p[..3].iter().all(|v|v.is_finite()){println!("BAD frame={frame} k={k} step={} cell=[{},{}] p={p:?}",frame*count*2+k+1,i%n,i/n);return}if p[0]<lo.0{lo=(p[0],i)}if p[0]>hi.0{hi=(p[0],i)}if p[1].hypot(p[2])>maxu.0{maxu=(p[1].hypot(p[2]),i)}}if k==count*2-1{println!("frame={frame} lo={} at=[{},{}] hi={} at=[{},{}] maxu={} at=[{},{}] ulat={}",lo.0,lo.1%n,lo.1/n,hi.0,hi.1%n,hi.1/n,maxu.0,maxu.1%n,maxu.1/n,maxu.0*dt/h);}}}println!("COMPLETE");}
